import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { 
  UserIcon, MapPinIcon, PhoneIcon, TruckIcon, 
  ClockIcon, GiftIcon, CheckCircleIcon, 
  HomeIcon, ShoppingBagIcon 
} from '@heroicons/react/24/outline';

const Orders = () => {
  const [order, setOrder] = useState({
    orderID: "ORD-2026-991",
    status: "Pending",
    items: [
      { name: "Keells Sugar 1kg", quantity: 2, isPacked: false },
      { name: "Anchor Milk Powder 400g", quantity: 1, isPacked: false }
    ],
    customer: {
      name: "Saman Kumara",
      phoneNumber: "071-2345678",
      address: { houseNumber: "No. 45/A", street: "Temple Road", landMark: "Near Clock Tower" }
    }
  });

  const statuses = ['Pending', 'Packing', 'Out for Delivery', 'Delivered'];
  const currentIdx = statuses.indexOf(order.status);

  return (
    <div className="flex min-h-screen bg-gray-100">
      {/* SIDEBAR */}
      <aside className="w-64 bg-blue-900 text-white flex flex-col">
        <div className="p-6 border-b border-blue-800">
          <h1 className="text-2xl font-bold text-yellow-400 flex items-center gap-2">
            <HomeIcon className="w-6 h-6" /> BigMart
          </h1>
        </div>
        <nav className="mt-6 flex-1">
          <Link to="/orders" className="flex items-center gap-3 px-6 py-4 bg-blue-700 border-r-4 border-yellow-400">
            <TruckIcon className="w-5 h-5 text-yellow-400" />
            <span className="font-bold">Active Orders</span>
          </Link>
          <Link to="/history" className="flex items-center gap-3 px-6 py-4 hover:bg-blue-800 transition-colors">
            <ShoppingBagIcon className="w-5 h-5" />
            <span>Order History</span>
          </Link>
        </nav>
      </aside>

      {/* MAIN CONTENT */}
      <div className="flex-1">
        <header className="bg-white shadow p-8 flex justify-between">
          <h2 className="text-3xl font-bold">Orders Management</h2>
          <span className="bg-blue-100 text-blue-700 px-4 py-1 rounded-full text-xs font-bold uppercase">{order.status}</span>
        </header>
        <main className="p-8">
          <div className="bg-white rounded-xl shadow p-6 border border-gray-200">
             <h3 className="text-xl font-bold mb-4">{order.orderID} - {order.customer.name}</h3>
             <p className="text-gray-600 mb-2 font-semibold italic">Deliver to: {order.customer.address.houseNumber}, {order.customer.address.street}</p>
             <div className="mt-6 p-4 bg-yellow-50 rounded-lg border border-yellow-100">
                <p className="text-sm font-bold text-yellow-800">Landmark: {order.customer.address.landMark}</p>
             </div>
          </div>
        </main>
      </div>
    </div>
  );
};

export default Orders;
